// Upload fixtures, generated by tools/fixtures.mjs into load/fixtures. Call `loadFixture` at init time only (it
// uses open()). `unique` returns a copy with the 16 byte slot overwritten, so every upload has its own hash.
const manifest = JSON.parse(open(import.meta.resolve('../fixtures/manifest.json')));

const crcTable = [];
for (let n = 0; n < 256; n++) {
  let c = n;
  for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
  crcTable.push(c >>> 0);
}

export function loadFixture(name) {
  const meta = manifest[name];
  if (!meta) throw new Error(`fixture ${name} is missing: run node load/tools/fixtures.mjs`);
  return { name, meta, base: new Uint8Array(open(import.meta.resolve(`../fixtures/${name}`), 'b')) };
}

/** token: at most 16 ASCII characters, padded with spaces. */
export function unique(fixture, token) {
  const { meta, base } = fixture;
  const bytes = new Uint8Array(base.length);
  bytes.set(base);
  for (let i = 0; i < meta.slotBytes; i++) bytes[meta.slotOffset + i] = (token.charCodeAt(i) || 32) & 0x7f;
  if (meta.kind === 'png') {
    // The slot sits in a tEXt chunk: its CRC covers the type and the body ("tEXt", "hm\0", slot).
    const from = meta.slotOffset - 3 - 4;
    const to = meta.slotOffset + meta.slotBytes;
    let c = 0xffffffff;
    for (let i = from; i < to; i++) c = crcTable[(c ^ bytes[i]) & 0xff] ^ (c >>> 8);
    const crc = (c ^ 0xffffffff) >>> 0;
    bytes[to] = crc >>> 24;
    bytes[to + 1] = (crc >>> 16) & 0xff;
    bytes[to + 2] = (crc >>> 8) & 0xff;
    bytes[to + 3] = crc & 0xff;
  }
  return bytes.buffer;
}

const CONTENT_TYPES = { png: 'image/png', webp: 'image/webp', jpeg: 'image/jpeg' };
export const contentTypeOf = (fixture) => CONTENT_TYPES[fixture.meta.kind];

/** Sixteen characters: run id, a two letter kind and a counter, unique per run, scenario and upload. */
export const tokenOf = (runId, kind, n) => `${runId}${kind}${String(n).padStart(8, '0')}`.slice(0, 16);
